package dev.cyberimplants.compat.create.ponder;

import dev.cyberimplants.CyberImplants;
import net.createmod.ponder.api.registration.PonderPlugin;
import net.createmod.ponder.api.registration.PonderSceneRegistrationHelper;
import net.minecraft.resources.ResourceLocation;

/**
 * Ponder scenes for the mod's blocks (Layer 5 teaching): hold W over a Rig, Charger, Etcher, Neural Port or Proximity
 * Sensor. Each scene loads {@code assets/cyberimplants/ponder/<block>.nbt} (generated by scripts/gen_data.py); the
 * texts are the {@code cyberimplants.ponder.*} language keys.
 */
public final class CyberPonderPlugin implements PonderPlugin {
    @Override
    public String getModId() {
        return CyberImplants.MOD_ID;
    }

    @Override
    public void registerScenes(PonderSceneRegistrationHelper<ResourceLocation> helper) {
        helper.forComponents(CyberImplants.id("implantation_rig")).addStoryBoard("implantation_rig", CyberPonderScenes::rig);
        helper.forComponents(CyberImplants.id("kinetic_charger")).addStoryBoard("kinetic_charger", CyberPonderScenes::charger);
        helper.forComponents(CyberImplants.id("precision_etcher")).addStoryBoard("precision_etcher", CyberPonderScenes::etcher);
        helper.forComponents(CyberImplants.id("neural_port")).addStoryBoard("neural_port", CyberPonderScenes::port);
        helper.forComponents(CyberImplants.id("proximity_sensor")).addStoryBoard("proximity_sensor", CyberPonderScenes::sensor);
    }
}
